{
  "name": "@zachary0528/opencode-pixel-pet",
  "version": "1.2.1",
  "description": "一个 opencode 插件：在终端与 Web UI 中养一只随编码成长、进化、互动的彩色像素宠物。支持社交功能和 AI 自动回答。",
  "type": "module",
  "exports": {
    ".": "./pixel-pet.ts"
  },
  "bin": {
    "opencode-pixel-pet-server": "./server.ts"
  },
  "files": [
    "pixel-pet.ts",
    "server.ts",
    "README.md",
    "LICENSE"
  ],
  "author": {
    "name": "Zachary Ai",
    "email": "zclqwe@outlook.com"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "pixel-pet",
    "pet",
    "gamification",
    "websocket",
    "social",
    "ai"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "publishConfig": {
    "access": "public"
  }
}
